ALTER TABLE "orchestrator_interview_kit_revisions" ADD CONSTRAINT "orchestrator_interview_kit_revisions_source_snapshot" CHECK (jsonb_typeof("orchestrator_interview_kit_revisions"."source_snapshot") = 'object' and "orchestrator_interview_kit_revisions"."source_snapshot" ?& array['optionId','title','url','version','recordHash','reviewBy'] and "orchestrator_interview_kit_revisions"."source_snapshot" - array['optionId','title','url','version','recordHash','reviewBy'] = '{}'::jsonb and "orchestrator_interview_kit_revisions"."source_snapshot"->>'recordHash' ~ '^[a-f0-9]{64}$');